<?php
/**
 * Proof — compose and the draft (email.md "Proof"): To as chips from the record's people with the opt-out marked, the template's merge fields filled (and the ones that cannot be marked),
 * several To's keeping the contact's fields for the send, an opted-out contact refused by name, a draft saved and changed and kept as its sender's alone (no one else sees it, not even in
 * a record's list), a file from the record on a draft, the reply, the no-JavaScript path. Nothing is sent by a draft.
 */
require __DIR__ . '/lib.php';
$x = run_tag();
ensure_mailbox();
$since = last_activity_id();
$acc = (int) post_as(26, '/accounts/save.php', ['name' => "Compose Acct $x"])['json']['record_id'];
$ann = contact_with("ann-$x@compose-$x.example.invalid", 'Ann', $acc);
$bob = contact_with("bob-$x@compose-$x.example.invalid", 'Bob', $acc);
$cat = contact_with("cat-$x@compose-$x.example.invalid", 'Cat', $acc);
$deal = deal_make(26, ['title' => "Compose deal $x", 'account' => $acc, 'primary_contact' => $ann]);
$r = post_as(26, '/contacts/opt-out.php', ['contact' => $bob, 'channel' => 'email', 'reason' => 'asked']);
ok($r['code'] === 200, 'setup: Bob opts out of email');
$intro = (int) one("SELECT id FROM email_templates WHERE name = 'Introduction' AND is_shared");
$sendsBefore = count(sends());

echo "1. The compose screen: To as chips, the opt-out marked\n";
$h = html_as(26, "/email/compose?contact=$ann")['body'];
ok(str_contains($h, 'id="compose-form"') && str_contains($h, 'id="compose-to-chip-' . $ann . '"') && preg_match('/id="compose-to-' . $ann . '"[^>]* checked/', $h) === 1, 'from a contact: their chip, ticked');
ok(str_contains($h, 'id="compose-to-chip-' . $bob . '"') && str_contains($h, 'id="compose-to-optout-' . $bob . '"') && preg_match('/id="compose-to-' . $bob . '"[^>]* disabled/', $h) === 1, 'the others at the account are offered; the one who opted out is marked and cannot be ticked');
$h = html_as(26, "/email/compose?deal=$deal")['body'];
ok(preg_match('/id="compose-to-' . $ann . '"[^>]* checked/', $h) === 1 && !preg_match('/id="compose-to-' . $cat . '"[^>]* checked/', $h) && str_contains($h, 'id="compose-to-chip-' . $cat . '"'), 'from a deal: the primary contact ticked, the account\'s others offered');
ok(str_contains($h, 'id="compose-send-btn"') && str_contains($h, 'id="compose-draft-btn"') && str_contains($h, 'id="compose-template-picker"') && str_contains($h, 'name="template"'), 'Send, Save draft and the template picker are there');
ok(preg_match('/<form[^>]*action="\/email\/draft\.php"[^>]*id="compose-form"/', $h) === 1 && str_contains($h, 'formaction="/email/send.php"'), 'the form\'s own action is the safe one (a draft); only the Send button sends');
$h = html_as(26, '/email/compose')['body'];
ok(str_contains($h, 'id="compose-to-empty"') && str_contains($h, 'id="compose-contact-picker"'), 'from nothing: "Choose who it is to" and the contact picker');
ok(html_as(26, '/email/compose?contact=999999999')['code'] === 404 && html_as(26, "/email/compose?template=999999999&contact=$ann")['code'] === 404, 'a contact or a template that is not there: 404');
$mkt = fixture()['claims']['31']; $mkt['roles'] = ['marketing']; $mkt['role'] = 'marketing';
$mj = sign_on(31, ['claims' => $mkt])[0];
ok(html_as(29, "/email/compose?contact=$ann")['code'] === 403 && page($mj, "/email/compose?contact=$ann")['code'] === 403, 'a Viewer and Marketing (who log no email) may not compose: 403');

echo "2. A template: the merge fields filled, the rest marked\n";
$h = html_as(26, "/email/compose?contact=$ann&deal=$deal&template=$intro")['body'];
preg_match('/<input[^>]*id="compose-subject"[^>]*value="([^"]*)"/', $h, $sm);
preg_match('/<textarea[^>]*id="compose-body"[^>]*>(.*?)<\/textarea>/s', $h, $bm);
$subject = html_entity_decode($sm[1] ?? '');
$body = html_entity_decode($bm[1] ?? '');
$company = (string) one('SELECT business_name FROM crm_settings');
ok(str_starts_with($body, 'Hi Ann,') && str_contains($body, "what you are working on at Compose Acct $x") && !str_contains($body, '{{'), 'the body greets the contact by first name and names the account; nothing is left standing: ' . substr($body, 0, 60));
ok(!str_contains($body, '\\n') && str_contains($body, "Hi Ann,\n\n"), 'the seeded template\'s lines are lines, not a backslash and an n');
ok(!str_contains($subject, '{{') && str_starts_with($subject, 'Hello from '), 'the subject is filled too: ' . $subject);
ok(str_contains($h, 'id="compose-preview-filled"') && str_contains($h, 'contact.first_name'), 'the preview lists what was filled');
$own = post_as(26, '/email/templates/save.php', ['name' => "Odd $x", 'subject' => 'About {{deal.title}} {{foo.bar}}', 'body' => "Hi {{contact.first_name}},\n\n{{deal.title}} and {{foo.bar}} and {{activity.date}}.", 'kind' => 'proposal'])['json']['record_id'];
$h = html_as(26, "/email/compose?contact=$ann&template=$own")['body'];
ok(str_contains($h, 'id="compose-preview-unknown"') && str_contains($h, '{{foo.bar}}') && str_contains($h, 'id="compose-preview-missing"') && str_contains($h, '{{deal.title}}') && str_contains($h, '{{activity.date}}'), 'a field that is none of ours is marked, and so is one with nothing to fill it (no deal, no meeting); both stay as typed');
$h = html_as(26, "/email/compose?contacts[]=$ann&contacts[]=$cat&deal=$deal&template=$intro")['body'];
preg_match('/<textarea[^>]*id="compose-body"[^>]*>(.*?)<\/textarea>/s', $h, $bm);
ok(str_contains(html_entity_decode($bm[1] ?? ''), 'Hi {{contact.first_name}},') && str_contains($h, 'id="compose-preview-when-sent"'), 'with two To\'s the contact\'s fields stay for the send, and the preview says so');
$h = html_as(26, "/email/compose?contact=$ann&deal=$deal")['body'];
ok(str_contains($h, 'id="compose-template-link-' . $intro . '"') && str_contains($h, 'template=' . $intro), 'without JavaScript: plain links start from a template');
$j = get_as(26, "/email/compose?contact=$ann&deal=$deal&template=$intro")['json']['data'] ?? [];
ok(($j['template_id'] ?? 0) === $intro && str_starts_with((string) ($j['body'] ?? ''), 'Hi Ann,') && array_filter($j['contacts'] ?? [], static fn ($c) => $c['contact_id'] === $bob && !$c['allowed'] && $c['opted_out']) !== [] && in_array('deal.title', $j['merge_fields'] ?? [], true), 'JSON: the people with their allowed/opted-out, the filled fields, the merge field names');
$hx = html_as(26, "/email/compose?contact=$ann&deal=$deal&template=$intro", ['HX-Request: true']);
ok(!str_contains($hx['body'], '<html') && str_contains($hx['body'], 'id="compose-fill"') && preg_match('/^X-Screen: email-compose\r?$/mi', $hx['headers']) === 1, 'over HTMX the page is the partial stamped email-compose, with the region the template refreshes');

echo "3. A draft is saved, changed and kept; nothing is sent\n";
$r = post_as(26, '/email/draft.php', ['contact' => $ann, 'deal' => $deal, 'subject' => "Draft $x", 'body' => "Hi Ann,\n\nA SECRET-DRAFT-BODY line.", 'template' => $intro]);
$d = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && $d > 0 && ($r['json']['ok'] ?? false), 'email_draft: ' . ($r['json']['did'] ?? $r['body']));
$o = q('SELECT * FROM outbound_email WHERE id = :i', ['i' => $d])[0] ?? [];
ok($o !== [] && $o['status'] === 'queued' && $o['sent_at'] === null && (int) $o['sender_member_id'] === 26 && (int) $o['contact_id'] === $ann && (int) $o['deal_id'] === $deal && (int) $o['template_id'] === $intro && $o['to_address'] === "ann-$x@compose-$x.example.invalid" && $o['message_id'] === null, 'the draft is an outbound_email row: queued, not sent, Priya\'s, to Ann, on the deal, with the template, no Message-ID yet');
ok(count(sends()) === $sendsBefore, 'nothing went to MaluMail');
$r = post_as(26, '/email/draft.php', ['draft' => $d, 'subject' => "Draft changed $x"]);
ok($r['code'] === 200 && (int) $r['json']['record_id'] === $d && one('SELECT subject FROM outbound_email WHERE id = :i', ['i' => $d]) === "Draft changed $x" && str_contains((string) one('SELECT body_text FROM outbound_email WHERE id = :i', ['i' => $d]), 'SECRET-DRAFT-BODY'), 'a field left out stays as it was: the subject changed, the body kept, the same draft');
$r = post_as(26, '/email/draft.php', ['contacts' => [$ann, $cat], 'subject' => "Two $x", 'body' => 'Hello both']);
$d2 = (int) ($r['json']['record_id'] ?? 0);
$o2 = q('SELECT * FROM outbound_email WHERE id = :i', ['i' => $d2])[0] ?? [];
ok($r['code'] === 200 && $o2['to_address'] === "ann-$x@compose-$x.example.invalid" && $o2['cc_addresses'] === "{cat-$x@compose-$x.example.invalid}", 'two people: the first is To, the other is kept for their own message at the send');
$rows = q("SELECT action, after::text AS after FROM activity_log WHERE id > :s AND action = 'email.draft'", ['s' => $since]);
ok(count($rows) === 3 && !str_contains(json_encode($rows), 'SECRET-DRAFT-BODY'), 'email.draft logged for each; the body is in no payload');

echo "4. A draft is its sender's alone\n";
ok(html_as(26, "/email/out/$d")['code'] === 200 && str_contains(html_as(26, "/email/out/$d")['body'], 'id="email-edit-btn"'), 'Priya opens her draft, with "Edit and send"');
ok(html_as(30, "/email/out/$d")['code'] === 404 && html_as(27, "/email/out/$d")['code'] === 404 && html_as(1, "/email/out/$d")['code'] === 404, 'another seller, the manager and the admin: the same 404 as a missing one');
ok(html_as(30, "/email/compose?draft=$d")['code'] === 404, 'nobody else opens it in compose');
$tab = html_as(26, "/contacts/$ann?tab=emails")['body'];
ok(str_contains($tab, 'id="contact-email-out-' . $d . '"') && str_contains($tab, '>draft<'), 'on the contact\'s Emails tab the sender sees it, as a draft');
ok(!str_contains(html_as(30, "/contacts/$ann?tab=emails")['body'], 'id="contact-email-out-' . $d . '"') && !str_contains(html_as(27, "/deals/$deal?tab=emails")['body'], 'id="deal-email-out-' . $d . '"'), 'to anyone else it is not on the tab');
$list = get_as(30, "/email/unmatched")['json']['data'] ?? [];
ok(array_filter($list['drafts'] ?? [], static fn ($x2) => $x2['draft_id'] === $d) === [], 'and not among their drafts');
$mine = get_as(26, "/email/unmatched")['json']['data'] ?? [];
ok(array_filter($mine['drafts'] ?? [], static fn ($x2) => $x2['draft_id'] === $d) !== [], 'it is among Priya\'s');
$r = post_as(30, '/email/draft.php', ['draft' => $d, 'subject' => 'stolen']);
ok($r['code'] === 404, 'another seller may not change it: 404');

echo "5. Refusals, in words\n";
$r = post_as(26, '/email/draft.php', ['contact' => $bob, 'subject' => 'x', 'body' => 'y']);
ok($r['code'] === 422 && str_contains((string) ($r['json']['error']['message'] ?? ''), 'Bob Mail') && str_contains((string) ($r['json']['error']['message'] ?? ''), 'opted out of email') && field_of($r) === 'contact', 'an opted-out contact is refused by name: ' . ($r['json']['error']['message'] ?? $r['body']));
$r = post_as(26, '/email/draft.php', ['contacts' => [$ann, $bob], 'subject' => 'x', 'body' => 'y']);
ok($r['code'] === 422 && str_contains((string) ($r['json']['error']['message'] ?? ''), 'Bob Mail'), 'one of several: the whole is refused');
$r = post_as(26, '/email/draft.php', ['subject' => 'x', 'body' => 'y']);
ok($r['code'] === 422 && field_of($r) === 'contact', 'no one to send to: the contact field is named');
$r = post_as(26, '/email/draft.php', ['contact' => $ann, 'body' => 'y']);
ok($r['code'] === 422 && field_of($r) === 'subject', 'no subject: named');
$r = post_as(26, '/email/draft.php', ['contact' => $ann, 'subject' => 'x']);
ok($r['code'] === 422 && field_of($r) === 'body', 'no message: named');
$r = post_as(26, '/email/draft.php', ['contact' => 999999999, 'subject' => 'x', 'body' => 'y']);
ok($r['code'] === 422 && field_of($r) === 'contact', 'a contact that is not there: refused');
$g = (int) post_as(27, '/accounts/save.php', ['name' => "Walled $x"])['json']['record_id'];
$walled = contact_with("walled-$x@walled-$x.example.invalid", 'Wall', $g, 27);
pg_run("UPDATE contacts SET restricted_to_member_id = 27 WHERE id = $walled");
$r = post_as(26, '/email/draft.php', ['contact' => $walled, 'subject' => 'x', 'body' => 'y']);
ok($r['code'] === 422 && field_of($r) === 'contact', 'a contact behind the wall is refused as if missing');
$r = post_as(29, '/email/draft.php', ['contact' => $ann, 'subject' => 'x', 'body' => 'y']);
ok($r['code'] === 403, 'a Viewer may not draft: 403');
$nocontact = (int) post_as(26, '/contacts/save.php', ['first_name' => 'Nora', 'last_name' => "Noaddr $x"])['json']['record_id'];
$r = post_as(26, '/email/draft.php', ['contact' => $nocontact, 'subject' => 'x', 'body' => 'y']);
ok($r['code'] === 422 && str_contains((string) ($r['json']['error']['message'] ?? ''), 'no email address'), 'a contact with no address: refused by name');

echo "6. A file from the record goes on the draft\n";
$f = tempnam(sys_get_temp_dir(), 'crmf') . '.txt';
file_put_contents($f, "price list $x\n");
$up = upload_as(26, '/attachments/add.php', ['kind' => 'deal', 'record' => $deal], [$f, 'text/plain', 'price list.txt']);
$att = (int) ($up['json']['record_id'] ?? $up['json']['attachment_id'] ?? one("SELECT id FROM attachments WHERE record_type = 'deal' AND record_id = :d ORDER BY id DESC LIMIT 1", ['d' => $deal]));
ok($att > 0, 'setup: a file on the deal');
$h = html_as(26, "/email/compose?deal=$deal")['body'];
ok(str_contains($h, 'id="compose-file-' . $att . '"'), 'compose offers the deal\'s files');
$r = post_as(26, '/email/draft.php', ['draft' => $d, 'attachments' => [$att]]);
$copies = q("SELECT * FROM attachments WHERE record_type = 'outbound_email' AND record_id = :d", ['d' => $d]);
ok($r['code'] === 200 && count($copies) === 1 && $copies[0]['filename'] === 'price-list.txt', 'the draft carries a copy of the row over the same bytes');
$h = html_as(26, "/email/compose?draft=$d")['body'];
ok(preg_match('/id="compose-file-' . $copies[0]['id'] . '"[^>]* checked/', $h) === 1 && substr_count($h, 'price-list.txt') === 1, 'reopened, the file is ticked (and listed once)');
$r = post_as(26, '/email/draft.php', ['draft' => $d, 'attachments' => ['']]);
ok($r['code'] === 200 && (int) one("SELECT count(*) FROM attachments WHERE record_type = 'outbound_email' AND record_id = :d", ['d' => $d]) === 0 && (int) one('SELECT count(*) FROM attachments WHERE id = :a', ['a' => $att]) === 1, 'taking it off removes the copy and leaves the deal\'s file');
post_as(26, '/email/draft.php', ['draft' => $d, 'attachments' => [$att]]);

echo "7. The no-JavaScript path and a reply\n";
[$jar, $csrf] = actor(26);
$res = req('POST', '/email/draft.php', ['jar' => $jar, 'headers' => ['X-CSRF-Token: ' . $csrf], 'form' => ['contacts' => [$cat], 'deal' => $deal, 'subject' => "Plain $x", 'body' => 'no javascript', 'return_to' => "/deals/$deal"]]);
ok($res['code'] === 302 && preg_match('#^/email/compose\?draft=\d+&back=%2Fdeals%2F\d+&notice=draft#', $res['location']) === 1, 'a plain form post is redirected back to the draft with a notice: ' . $res['location']);
$res = req('POST', '/email/draft.php', ['jar' => $jar, 'headers' => ['X-CSRF-Token: ' . $csrf], 'form' => ['contacts' => [$bob], 'subject' => 'x', 'body' => 'y']]);
ok($res['code'] === 422 && str_contains($res['body'], 'opted out of email'), 'and a refusal is a page in words');
$res = req('POST', '/email/draft.php', ['form' => ['contacts' => [$cat], 'subject' => 'x', 'body' => 'y']]);
ok(in_array($res['code'], [302, 401, 403], true) && (int) one("SELECT count(*) FROM outbound_email WHERE subject = 'x' AND body_text = 'y' AND sender_member_id IS NULL") === 0, 'without a session: sent to the launcher, nothing written');
$res = req('POST', '/email/draft.php', ['jar' => $jar, 'form' => ['contacts' => [$cat], 'subject' => 'no csrf', 'body' => 'y']]);
ok($res['code'] === 403 && (int) one("SELECT count(*) FROM outbound_email WHERE subject = 'no csrf'") === 0, 'with a session but no CSRF token: 403, nothing written');
$m = '<in-' . $x . '@compose-' . $x . '.example.invalid>';
deliver(msg("Ann <ann-$x@compose-$x.example.invalid>", [MAILBOX], 'Can you do Thursday?', 'Can we meet on Thursday?', [], ['message-id' => $m]));
worker('mail_match');
$in = inbound($m);
$h = html_as(26, '/email/in/' . $in['id'])['body'];
ok(str_contains($h, 'id="email-reply-btn"'), 'a received email has Reply');
$h = html_as(26, '/email/compose?reply=' . $in['id'])['body'];
preg_match('/<input[^>]*id="compose-subject"[^>]*value="([^"]*)"/', $h, $sm);
ok(html_entity_decode($sm[1] ?? '') === 'Re: Can you do Thursday?' && preg_match('/id="compose-to-' . $ann . '"[^>]* checked/', $h) === 1 && str_contains($h, 'name="reply" value="' . $in['id'] . '"'), 'Reply opens compose to the one who wrote, "Re:" the subject, keeping what it answers');
$r = post_as(26, '/email/draft.php', ['contact' => $ann, 'subject' => 'Re: Can you do Thursday?', 'body' => 'Yes.', 'reply' => $in['id']]);
$dr = q('SELECT in_reply_to, references_ids FROM outbound_email WHERE id = :i', ['i' => $r['json']['record_id']])[0] ?? [];
ok($dr['in_reply_to'] === $m && str_contains((string) $dr['references_ids'], $m), 'the draft keeps In-Reply-To and References');
finish();
